head.b:skin:
@@RS_TOKENS_CSS@@

* { box-sizing: border-box; }
body {
  margin: 0; background: var(--rs-bg); color: var(--rs-fg);
  font: 16px/1.65 var(--rs-font-text);
}
a { color: var(--rs-accent); text-decoration: none; }
a:hover { color: var(--rs-accent-hover); text-decoration: underline; }
.site { max-width: 46rem; margin: 0 auto; padding: 0 1rem; }
.site-header { display: flex; align-items: center; gap: 1rem; padding: 2rem 0 1.5rem; border-bottom: 1px solid var(--rs-line); }
.site-header svg { height: 3rem; width: auto; flex: none; }
.site-header .widget { margin: 0; }
.site-header h1 { font-size: 1.4rem; margin: 0; letter-spacing: .04em; }
.site-header h1 a { color: var(--rs-fg); }
.site-header .description { margin: .2rem 0 0; color: var(--rs-muted); }
.date-header { color: var(--rs-muted); font-size: .85rem; margin: 2.5rem 0 .25rem; }
.post-outer { padding-bottom: 1.5rem; border-bottom: 1px solid var(--rs-line); }
.post-title { font-size: 1.5rem; line-height: 1.3; margin: .25rem 0 1rem; }
.post-title a { color: var(--rs-fg); }
.post-body img { max-width: 100%; height: auto; border-radius: var(--rs-radius-sm); }
.post-body pre, .post-body code {
  font-family: var(--rs-font-mono); background: var(--rs-accent-soft);
  border-radius: var(--rs-radius-sm);
}
.post-body pre { padding: .75rem 1rem; overflow-x: auto; }
.post-body code { padding: .1rem .3rem; }
.post-body blockquote { margin: 1rem 0; padding-left: 1rem; border-left: 3px solid var(--rs-highlight); color: var(--rs-muted); }
.post-footer, .post-labels { font-size: .85rem; color: var(--rs-muted); }
.post-labels a { color: var(--rs-highlight); }
.blog-pager { display: flex; justify-content: space-between; padding: 2rem 0; }
.comments { margin-top: 2rem; }
.site-footer { color: var(--rs-muted); font-size: .8rem; padding: 2rem 0; }
.site-footer .widget { margin: 0 0 1rem; }
